type ErrorCategory = 'recoverable' | 'fatal';

type AuthStepId =
  | 'signing_in'
  | 'checking_account'
  | 'restoring_session'
  | 'creating_account'
  | 'loading_profile'
  | 'connecting_wallet'
  | 'setting_up_wallet';

